const medicines = [
  { name: 'Paracetamol', generic: 'Acetaminophen', className: 'Analgesic · Antipyretic', use: 'Pain and fever relief', color: 'mint', icon: '✚' },
  { name: 'Cetirizine', generic: 'Cetirizine HCl', className: 'Antihistamine', use: 'Allergy symptom relief', color: 'lavender', icon: '✦' },
  { name: 'Omeprazole', generic: 'Omeprazole', className: 'Proton pump inhibitor', use: 'Acid reflux support', color: 'peach', icon: '◒' },
  { name: 'ORS', generic: 'Oral rehydration salts', className: 'Electrolyte solution', use: 'Fluid and electrolyte replacement', color: 'yellow', icon: '⌁' }
];

const app = document.querySelector('#app');
const API_HOST = window.location.hostname === '127.0.0.1' ? '127.0.0.1' : 'localhost';
const API_BASE_URL = window.MEDI_DOST_API_URL || `http://${API_HOST}:4173`;
const toast = (message) => { const el = document.querySelector('#toast'); el.textContent = message; el.classList.add('show'); setTimeout(() => el.classList.remove('show'), 2400); };
const medCards = (items = medicines) => items.map((med) => `<article class="medicine-card ${med.color}"><div class="medicine-icon">${med.icon}</div><button class="bookmark" aria-label="Save ${med.name}" data-save="${med.name}">♡</button><p class="overline">${med.className}</p><h3>${med.name}</h3><p>${med.generic}</p><div class="card-footer"><span>${med.use}</span><button class="text-action" data-video="${med.name}">Watch story <span>↗</span></button></div></article>`).join('');
async function api(url, options = {}) { const target = /^https?:\/\//i.test(url) ? url : `${API_BASE_URL}${url}`; const response = await fetch(target, { credentials: 'include', headers: { 'Content-Type': 'application/json' }, ...options }); const contentType = response.headers.get('content-type') || ''; const raw = await response.text(); let payload = null; if (raw.trim()) { try { payload = JSON.parse(raw); } catch { throw new Error(response.ok ? 'The server returned an invalid response. Please try again.' : `The server returned ${response.status} without a valid JSON error.`); } } else if (!response.ok) { throw new Error(`The server returned ${response.status} without a response. Please try again.`); } else if (!contentType.includes('application/json')) { throw new Error('The server returned an unexpected response. Please start the Medi Dost backend.'); } else { throw new Error('The server returned an empty response. Please try again.'); } if (!response.ok) { const message = typeof payload.error === 'string' ? payload.error : payload.error?.message || payload.details?.message || 'Something went wrong.'; throw new Error(message); } if (payload.success && payload.data !== undefined) return payload.data && typeof payload.data === 'object' && !Array.isArray(payload.data) ? { ...payload.data, ...payload } : payload.data; return payload; }
function loginView(error = '') { app.innerHTML = `<main class="login-page"><div class="login-art"><a class="logo" href="#"><span class="logo-mark">+</span><span>Medi <b>Dost</b></span></a><div class="login-orbit"><span>✦</span><b>+</b></div><div><p class="overline">YOUR SMART FRIEND FOR BETTER HEALTH</p><h1>Health questions?<br><em>Ask Medi Dost.</em></h1><p>Clear, careful health information for the moments you need it.</p></div></div><section class="login-card"><div class="login-card-heading"><span class="ai-badge"><span>✦</span> Welcome back</span><h2>Sign in to<br><em>Medi Dost.</em></h2><p>Continue your health journey with your personal companion.</p></div><form id="login-form"><label for="login-email">Email address</label><input id="login-email" type="email" value="devraj@example.com" placeholder="you@example.com" required><label for="login-password">Password</label><div class="password-field"><input id="login-password" type="password" value="medidost123" placeholder="Your password" required><button type="button" id="show-password">Show</button></div><p class="login-error" id="login-error">${error}</p><button class="primary-button login-button" type="submit">Sign in <span>→</span></button><div class="login-divider"><span>or</span></div><button class="social-button" type="button" id="guest-login">Continue with demo access</button><p class="login-help">Demo: <b>devraj@example.com</b> · <b>medidost123</b></p><p class="login-legal">By continuing, you agree that Medi Dost provides general health information and does not replace a qualified doctor, pharmacist, or emergency service.</p></form></section></main>`; document.querySelector('#login-form').addEventListener('submit', async (event) => { event.preventDefault(); const errorEl = document.querySelector('#login-error'); const button = event.target.querySelector('button[type="submit"]'); button.disabled = true; button.textContent = 'Signing in...'; try { await api('/api/login', { method: 'POST', body: JSON.stringify({ email: document.querySelector('#login-email').value, password: document.querySelector('#login-password').value }) }); render(); } catch (error) { errorEl.textContent = error.message; button.disabled = false; button.innerHTML = 'Sign in <span>→</span>'; } }); document.querySelector('#show-password').addEventListener('click', () => { const input = document.querySelector('#login-password'); input.type = input.type === 'password' ? 'text' : 'password'; }); document.querySelector('#guest-login').addEventListener('click', () => document.querySelector('#login-form').requestSubmit()); }

function shell(content) { content = content.replaceAll('Arjun', 'Devraj').replaceAll('ARJUN', 'DEVRAJ'); app.innerHTML = `<div class="app-shell"><aside class="sidebar"><a class="logo" href="#home"><span class="logo-mark">+</span><span>Medi <b>Dost</b></span></a><p class="side-label">Workspace</p><nav class="side-nav" aria-label="Main navigation"><button class="nav-item active" data-view="home"><span>⌂</span> Home</button><button class="nav-item" data-view="ai"><span>✦</span> AI Assistant</button><button class="nav-item" data-view="medicines"><span>▣</span> Medicines</button><button class="nav-item" data-view="reminders"><span>◷</span> Reminders <i>2</i></button><button class="nav-item" data-view="reports"><span>▤</span> Health reports</button><button class="nav-item" data-view="tools"><span>⌘</span> Health tools</button></nav><p class="side-label side-label-bottom">Your space</p><nav class="side-nav"><button class="nav-item" data-view="saved"><span>♡</span> Saved medicines</button><button class="nav-item" data-view="profile"><span>◎</span> Profile</button></nav><div class="sidebar-emergency"><span>⚕</span><div><strong>Emergency help</strong><small>Get urgent support</small></div><b>↗</b></div><p class="sidebar-disclaimer">Medi Dost provides health information and does not replace a qualified doctor, pharmacist, or emergency service.</p></aside><div class="main-wrap"><header class="topbar"><div class="mobile-brand"><span class="logo-mark">+</span> Medi <b>Dost</b></div><div class="global-search"><span>⌕</span><input id="global-search" placeholder="Search medicines, symptoms, articles..." /><kbd>⌘ K</kbd></div><div class="top-actions"><button class="icon-button" id="theme-toggle" aria-label="Toggle dark mode">◐</button><button class="language-button" id="language-toggle">EN <span>⌄</span></button><button class="profile-chip" data-view="profile"><span>DA</span><b>Devraj Anand</b><small>⌄</small></button></div></header><main id="page-content">${content}</main></div></div><div class="toast" id="toast" role="status"></div>`; bindShell(); }
function homeView() { shell(`<section class="page home-page"><div class="welcome-row"><div><p class="overline teal"><h1>Good morning, Arjun <span>✦</span></h1><p class="muted">Let’s make today a little healthier.</p></div><button class="outline-button" data-view="profile">Your health profile <span>↗</span></button></div><section class="hero-panel"><div class="hero-copy"><span class="ai-badge"><span>✦</span> Medi Dost AI</span><h2>Health questions?<br><em>Ask Medi Dost.</em></h2><p>Understand medicines, symptoms and health information in simple language.</p><div class="ask-box"><input id="hero-question" placeholder="Ask anything about your health..." /><button id="ask-hero">→</button><div class="ask-tools"><button>♩ <small>Voice</small></button><button>⊙ <small>Upload</small></button><span>Try: “What is paracetamol used for?”</span></div></div></div><div class="hero-orbit"><div class="orbit-circle"></div><div class="hero-cross">+</div><div class="hero-spark">✦</div><div class="hero-caption">A smarter way<br>to feel informed</div></div></section><div class="section-title"><div><p class="overline teal">AT A GLANCE</p><h2>Today, for you</h2></div><button class="text-action" data-view="reminders">View all <span>↗</span></button></div><div class="stats-grid"><div class="stat-card"><div class="stat-icon mint-bg">◷</div><p class="overline">MEDICINE REMINDERS</p><strong>2 <small>left today</small></strong><div class="progress"><span style="width:66%"></span></div><a data-view="reminders">See schedule →</a></div><div class="stat-card"><div class="stat-icon peach-bg">♡</div><p class="overline">SAVED MEDICINES</p><strong>4 <small>in your shelf</small></strong><a data-view="saved">Open medicine shelf →</a></div><div class="stat-card"><div class="stat-icon lavender-bg">✦</div><p class="overline">RECENT QUESTIONS</p><strong>8 <small>this month</small></strong><a data-view="ai">Continue with AI →</a></div></div><div class="section-title medicines-heading"><div><p class="overline teal">YOUR MEDICINE SHELF</p><h2>Saved medicines</h2></div><button class="text-action" data-view="medicines">Browse database <span>↗</span></button></div><div class="medicine-grid">${medCards(medicines.slice(0, 3))}</div><section class="safety-banner"><div class="safety-symbol">⚕</div><div><p class="overline">A LITTLE REMINDER</p><h3>Health information should feel clear,<br>not confusing.</h3><p>Medi Dost helps you understand. Important decisions belong with your doctor or pharmacist.</p></div><button class="outline-button" data-view="tools">Explore health tools <span>↗</span></button></section></section>`); }
function aiView(prefill = '') { shell(`<section class="page ai-page"><div class="page-heading"><div><p class="overline teal">YOUR HEALTH COMPANION</p><h1>Medi Dost <em>AI</em></h1><p class="muted">Simple, careful answers for everyday health questions.</p></div><span class="online-pill"><i></i> Ready to help</span></div><div class="chat-layout"><div class="chat-window"><div class="chat-top"><span class="ai-badge"><span>✦</span> Medi Dost AI</span><button class="icon-button">•••</button></div><div class="messages"><div class="message ai-message"><span class="message-avatar">✦</span><div><p>Hi Arjun, I’m here to help you understand your health information.</p><p>What would you like to know today?</p><small>Just now</small></div></div><div class="suggestions"><button data-question="What is Paracetamol used for?">What is Paracetamol used for?</button><button data-question="Explain my medicine side effects">Explain medicine side effects</button><button data-question="Can I check two medicines together?">Check an interaction</button></div></div><form class="chat-input" id="chat-form"><input id="chat-input" value="${prefill}" placeholder="Ask about a medicine, symptom or report..." required /><button type="button" class="input-icon">♩</button><button type="submit">→</button></form></div><aside class="chat-aside"><div class="guardrail-card"><span>⚕</span><strong>Thoughtful by design</strong><p>Answers are educational, not a diagnosis. For urgent concerns, contact local emergency services.</p></div><div class="recent-card"><p class="overline">RECENTLY ASKED</p><button data-question="What should I know before taking a medicine?">Before taking a medicine <span>↗</span></button><button data-question="What do these blood test results mean?">Understand a blood report <span>↗</span></button></div></aside></div></section>`); bindAI(); }
function medicinesView() { shell(`<section class="page"><div class="page-heading"><div><p class="overline teal">MEDICINE DATABASE</p><h1>Find your <em>medicine.</em></h1><p class="muted">Reliable, plain-language information for everyday decisions.</p></div><button class="primary-button" data-view="tools">＋ Scan a medicine</button></div><div class="database-tools"><div class="database-search">⌕ <input id="medicine-search" placeholder="Search medicines, ingredients, or classes..." /></div><button class="filter-button">Search source <span>⌄</span></button></div><div class="medicine-grid full-grid" id="medicine-results">${medCards()}</div><p class="safety-note">ⓘ Information is educational and source-limited. Confirm important medication decisions with a doctor or pharmacist.</p></section>`); const input = document.querySelector('#medicine-search'); let timer; input.addEventListener('input', () => { clearTimeout(timer); const query = input.value.trim(); if (!query) { document.querySelector('#medicine-results').innerHTML = medCards(); return; } document.querySelector('#medicine-results').innerHTML = '<div class="loading-state">Searching the medicine reference...</div>'; timer = setTimeout(async () => { try { const result = await api(`/api/search?q=${encodeURIComponent(query)}`); document.querySelector('#medicine-results').innerHTML = medCards(result.medicines || []); if (!result.medicines?.length) document.querySelector('#medicine-results').innerHTML = '<div class="empty-state">No medicine information found for that search.</div>'; } catch (error) { document.querySelector('#medicine-results').innerHTML = `<div class="error-state">${error.message}</div>`; } }, 250); }); }
async function savedView() { shell(`<section class="page"><div class="page-heading"><div><p class="overline teal">YOUR SPACE</p><h1>Saved <em>medicines.</em></h1><p class="muted">Your personal shelf of medicine information.</p></div></div><div class="medicine-grid full-grid" id="saved-results"><div class="loading-state">Loading your medicine shelf...</div></div></section>`); try { const result = await api('/api/saved-medicines'); const items = result.data || result; document.querySelector('#saved-results').innerHTML = items.length ? medCards(items) : '<div class="empty-state">No saved medicines yet. Save one from the medicine database.</div>'; } catch (error) { document.querySelector('#saved-results').innerHTML = `<div class="error-state">${error.message}</div>`; } }
function remindersView() { shell(`<section class="page"><div class="page-heading"><div><p class="overline teal">YOUR ROUTINE</p><h1>Medicine <em>reminders.</em></h1><p class="muted">Create reminders for your own routine. They are not prescriptions.</p></div><button class="primary-button" id="add-reminder">＋ Add reminder</button></div><div class="reminder-layout"><div class="today-card"><div class="today-header"><div><p class="overline">YOUR SAVED ROUTINE</p><h2>Upcoming reminders</h2></div></div><div id="reminder-results"><div class="loading-state">Loading your reminders...</div></div></div><aside class="adherence-card"><p class="overline">SAFETY NOTE</p><p class="muted">Reminders are user-created prompts only. Confirm medicine decisions and schedules with a doctor or pharmacist.</p></aside></div></section>`); loadReminders(); }
async function loadReminders() { try { const result = await api('/api/reminders'); const reminders = result.data || result; const target = document.querySelector('#reminder-results'); target.innerHTML = reminders.length ? reminders.map(item => `<div class="reminder-item"><span class="time">${new Date(item.scheduled_at).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span><span class="reminder-pill mint-bg">◷</span><div><strong>${item.medicine_name}</strong><p>${item.note || 'User-created reminder'}</p></div><button class="snooze-button" data-delete-reminder="${item.id}">Delete</button></div>`).join('') : '<div class="empty-state">No reminders yet. Add one for your own routine.</div>'; } catch (error) { document.querySelector('#reminder-results').innerHTML = `<div class="error-state">${error.message}</div>`; } }
function toolsView() { shell(`<section class="page"><div class="page-heading"><div><p class="overline teal">HEALTH TOOLS</p><h1>Clarity, <em>at hand.</em></h1><p class="muted">Explore information tools built for everyday health questions.</p></div></div><div class="tools-grid"><button class="tool-card tool-teal" data-view="ai"><span>✦</span><h3>Ask Medi Dost AI</h3><p>Get simple, structured information about medicines and symptoms.</p><b>Open assistant ↗</b></button><button class="tool-card tool-yellow"><span>⚗</span><h3>Check interactions</h3><p>See what to discuss with your pharmacist when medicines meet.</p><b>Check medicines ↗</b></button><button class="tool-card tool-lavender"><span>⌁</span><h3>Understand a report</h3><p>Upload a lab report and learn what the numbers generally measure.</p><b>Upload report ↗</b></button><button class="tool-card tool-peach"><span>▧</span><h3>Prescription scanner</h3><p>Make a readable list from a prescription, with uncertain text flagged.</p><b>Scan prescription ↗</b></button></div><section class="emergency-panel"><span class="emergency-icon">⚠</span><div><p class="overline">NEED URGENT HELP?</p><h2>Emergencies need people,<br>not an AI.</h2><p>For severe difficulty breathing, chest pain, loss of consciousness, seizure, serious allergic reaction or severe bleeding, contact local emergency services immediately.</p></div><button class="danger-button" id="emergency-button">Emergency help ↗</button></section></section>`); }
function reportsView() { shell(`<section class="page"><div class="page-heading"><div><p class="overline teal">HEALTH REPORTS</p><h1>Understand your <em>numbers.</em></h1><p class="muted">A clearer starting point for a conversation with your clinician.</p></div><button class="primary-button" id="upload-report">⊙ Upload report</button></div><div class="report-empty"><div class="report-illustration">▤</div><h2>No reports yet</h2><p>Upload a blood test, CBC, lipid profile, thyroid or other common lab report to start.</p><button class="outline-button" id="upload-report-2">Choose a file <span>↗</span></button><small>JPG, PNG, WEBP or PDF · Files are not uploaded in this local preview.</small></div></section>`); }
function profileView() { shell(`<section class="page"><div class="page-heading"><div><p class="overline teal">YOUR SPACE</p><h1>Hi, <em>Devraj.</em></h1><p class="muted">Keep your health information private and in your hands.</p></div><button class="outline-button" id="logout">Log out <span>↗</span></button></div><div class="profile-layout"><div class="profile-card"><div class="profile-avatar">DA</div><h2>Devraj Anand</h2><p class="muted">arjun@example.com</p><button class="primary-button">Edit profile</button><div class="profile-list"><div><span>Age</span><b>29 years</b></div><div><span>Allergies</span><b>None added</b></div><div><span>Emergency contact</span><b>Not added</b></div></div></div><div class="privacy-card"><p class="overline teal">PRIVACY FIRST</p><h2>Your information is yours.</h2><p>Medi Dost only asks for information that helps make your experience useful. In a connected product, health data would be encrypted and managed with clear consent controls.</p><button class="text-action">Privacy settings <span>↗</span></button></div></div></section>`); }
function bindShell() { document.querySelectorAll('[data-view]').forEach((el) => el.addEventListener('click', () => render(el.dataset.view))); document.querySelector('#theme-toggle').addEventListener('click', () => { document.body.classList.toggle('dark-mode'); localStorage.setItem('medi-dark', document.body.classList.contains('dark-mode')); }); document.querySelector('#language-toggle').addEventListener('click', () => toast('Language menu ready: English · Hindi · Hinglish')); document.querySelector('#global-search').addEventListener('input', (e) => { if (e.target.value.trim()) render('medicines'); }); document.querySelectorAll('[data-ask]').forEach((el) => el.addEventListener('click', () => aiView(`Tell me about ${el.dataset.ask}`))); const askButton = document.querySelector('#ask-hero'); if (askButton) askButton.addEventListener('click', () => aiView(document.querySelector('#hero-question').value || 'What can you help me with?')); document.querySelectorAll('[data-taken]').forEach((el) => el.addEventListener('click', () => { el.textContent = '✓ Taken'; el.classList.add('confirmed'); toast(`${el.dataset.taken} marked as taken`); })); const addReminder = document.querySelector('#add-reminder'); if (addReminder) addReminder.addEventListener('click', () => toast('Reminder form is ready to connect to your account')); const emergency = document.querySelector('#emergency-button'); if (emergency) emergency.addEventListener('click', () => toast('Please call your local emergency service now')); document.querySelectorAll('#upload-report,#upload-report-2').forEach((el) => el.addEventListener('click', () => toast('Upload flow is ready to connect to secure storage'))); }
function bindAI() { document.querySelectorAll('[data-question]').forEach((button) => button.addEventListener('click', () => { document.querySelector('#chat-input').value = button.dataset.question; })); document.querySelector('#chat-form').addEventListener('submit', async (event) => { event.preventDefault(); const input = document.querySelector('#chat-input'); if (!input.value.trim()) return; const question = input.value.trim(); const messages = document.querySelector('.messages'); messages.insertAdjacentHTML('beforeend', `<div class="message user-message"><div><p>${question}</p><small>Just now</small></div></div><div class="message ai-message typing-message"><span class="message-avatar">✦</span><div><p>Thinking carefully...</p></div></div>`); input.value = ''; try { const result = await api('/api/chat', { method: 'POST', body: JSON.stringify({ question }) }); document.querySelector('.typing-message').outerHTML = `<div class="message ai-message"><span class="message-avatar">✦</span><div><p><strong>${result.answer.summary}</strong></p>${result.answer.sections.map(section => `<p><b>${section.title}:</b> ${section.text}</p>`).join('')}<small>Just now · General information</small></div></div>`; } catch (error) { document.querySelector('.typing-message').outerHTML = `<div class="message ai-message"><span class="message-avatar">!</span><div><p>${error.message}</p><small>Please try again</small></div></div>`; } }); }
document.addEventListener('click', async (event) => { const videoButton = event.target.closest('[data-video]'); if (videoButton) return medicineVideoView(videoButton.dataset.video); const saveButton = event.target.closest('[data-save]'); if (saveButton) { try { await api('/api/saved-medicines', { method: 'POST', body: JSON.stringify({ name: saveButton.dataset.save }) }); saveButton.textContent = '♥'; saveButton.classList.add('saved'); toast(`${saveButton.dataset.save} saved to your shelf`); } catch (error) { toast(error.message); } return; } if (event.target.closest('#logout')) { await api('/api/logout', { method: 'POST' }); loginView(); } });
document.addEventListener('click', (event) => { if (event.target.closest('.hero-orbit')) medicineVideoView('Paracetamol'); });
document.addEventListener('click', (event) => { const tab = event.target.closest('[data-view]'); if (!tab) return; event.preventDefault(); render(tab.dataset.view); });
document.addEventListener('click', async (event) => { const deleteButton = event.target.closest('[data-delete-reminder]'); if (deleteButton) { await api(`/api/reminders/${deleteButton.dataset.deleteReminder}`, { method: 'DELETE' }); loadReminders(); return; } if (event.target.closest('#add-reminder')) { const medicineName = window.prompt('Medicine name for this reminder:'); if (!medicineName) return; const scheduledAt = window.prompt('Date and time (for example 2026-09-20T08:00):'); if (!scheduledAt) return; try { await api('/api/reminders', { method: 'POST', body: JSON.stringify({ medicineName, scheduledAt }) }); toast('Reminder created'); loadReminders(); } catch (error) { toast(error.message); } } });
function setPrimaryLoginEmail() { const input = document.querySelector('#login-email'); if (input) input.value = 'devraj@example.com'; }
async function boot() { if (localStorage.getItem('medi-dark') === 'true') document.body.classList.add('dark-mode'); try { const session = await api('/api/session'); if (session.authenticated) render(); else loginView(); } catch { loginView('The service is unavailable. Please try again.'); } }
function featureView(title, eyebrow, subtitle, body) { shell(`<section class="page"><div class="page-heading"><div><p class="overline teal">${eyebrow}</p><h1>${title}</h1><p class="muted">${subtitle}</p></div><button class="outline-button" data-view="home">Back home <span>↗</span></button></div>${body}</section>`); }
function symptomsView() { featureView('Understand your <em>symptoms.</em>', 'SYMPTOM CHECKER', 'A structured starting point, never a diagnosis.', `<div class="feature-form"><label for="symptoms-input">What are you experiencing?</label><textarea id="symptoms-input" placeholder="For example: fever, cough and sore throat for two days"></textarea><div class="form-row"><label>Age group<select id="symptoms-age"><option>Adult</option><option>Child</option><option>Older adult</option></select></label><label>How severe?<select id="symptoms-severity"><option>Mild</option><option>Moderate</option><option>Severe</option></select></label></div><button class="primary-button" id="symptoms-submit">Explore possibilities <span>→</span></button><div id="symptoms-result"></div></div>`); document.querySelector('#symptoms-submit').addEventListener('click', async () => { const result = document.querySelector('#symptoms-result'); result.innerHTML = '<div class="loading-state">Reviewing your information carefully...</div>'; try { const data = await api('/api/symptoms', { method: 'POST', body: JSON.stringify({ symptoms: document.querySelector('#symptoms-input').value, age: document.querySelector('#symptoms-age').value, severity: document.querySelector('#symptoms-severity').value }) }); result.innerHTML = `<div class="result-card"><p class="overline teal">POSSIBLE EXPLANATIONS</p><ul>${data.possible.map(item => `<li>${item}</li>`).join('')}</ul><p><b>General self-care:</b> ${data.selfCare}</p><p><b>Red flags:</b> ${data.redFlags}</p></div>`; } catch (error) { result.innerHTML = `<div class="error-state">${error.message}</div>`; } }); }
function interactionsView() { featureView('Check medicine <em>interactions.</em>', 'INTERACTION CHECKER', 'Add medicines, supplements, or common products to discuss with a pharmacist.', `<div class="feature-form"><label for="interaction-a">Medicine 1</label><input id="interaction-a" placeholder="e.g. Paracetamol"><label for="interaction-b">Medicine 2</label><input id="interaction-b" placeholder="e.g. Warfarin"><label for="interaction-c">Optional supplement or food</label><input id="interaction-c" placeholder="e.g. Alcohol or a supplement"><button class="primary-button" id="interaction-submit">Check combination <span>→</span></button><div id="interaction-result"></div></div>`); document.querySelector('#interaction-submit').addEventListener('click', async () => { const medicinesToCheck = ['interaction-a', 'interaction-b', 'interaction-c'].map(id => document.querySelector(`#${id}`).value.trim()).filter(Boolean); const result = document.querySelector('#interaction-result'); result.innerHTML = '<div class="loading-state">Checking the combination...</div>'; try { const data = await api('/api/interactions', { method: 'POST', body: JSON.stringify({ medicines: medicinesToCheck }) }); result.innerHTML = `<div class="result-card"><span class="severity-badge">${data.result.severity}</span><h3>${data.medicines.join(' + ')}</h3><p>${data.result.detail}</p><p class="safety-note">Confirm important combinations with a doctor or pharmacist. Never assume a combination is 100% safe.</p></div>`; } catch (error) { result.innerHTML = `<div class="error-state">${error.message}</div>`; } }); }
function articlesView() { featureView('Learn something <em>useful.</em>', 'HEALTH LIBRARY', 'Short, calm explainers for everyday health questions.', `<div class="article-filters"><button class="filter-button">Medicines</button><button class="filter-button">Nutrition</button><button class="filter-button">First aid</button><button class="filter-button">Mental wellbeing</button></div><div class="article-grid"><article><span class="article-tag">MEDICINES · 4 MIN</span><h2>How to read a medicine label</h2><p>Understand active ingredients, warnings, storage instructions, and when to ask a pharmacist.</p><button class="text-action">Read article ↗</button></article><article><span class="article-tag">PREVENTION · 3 MIN</span><h2>What your body is telling you</h2><p>How to notice patterns without turning every symptom into a diagnosis.</p><button class="text-action">Read article ↗</button></article><article><span class="article-tag">FIRST AID · 5 MIN</span><h2>When an emergency is an emergency</h2><p>Recognize warning signs that should move you from searching to calling for help.</p><button class="text-action">Read article ↗</button></article></div>`); }
function compareView() { featureView('Compare with <em>context.</em>', 'MEDICINE COMPARISON', 'Compare general information without substituting one prescription for another.', `<div class="compare-box"><div><label>Medicine A<select id="compare-a"><option>Paracetamol</option><option>Cetirizine</option><option>Omeprazole</option></select></label><label>Medicine B<select id="compare-b"><option>Cetirizine</option><option>Paracetamol</option><option>ORS</option></select></label></div><div class="comparison-table"><div><b>Attribute</b><b id="compare-a-name">Paracetamol</b><b id="compare-b-name">Cetirizine</b></div><div><span>General use</span><span>Pain and fever</span><span>Allergy symptoms</span></div><div><span>Class</span><span>Analgesic</span><span>Antihistamine</span></div><div><span>Important note</span><span>Follow label directions</span><span>May cause drowsiness</span></div></div><p class="safety-note">A comparison is educational. Do not change or substitute prescription medicines without professional guidance.</p></div>`); document.querySelectorAll('#compare-a,#compare-b').forEach(input => input.addEventListener('change', () => toast('Comparison updated for the selected medicines'))); }
function scannerView(kind = 'medicine') { const title = kind === 'prescription' ? 'Read a <em>prescription.</em>' : 'Scan a <em>medicine.</em>'; featureView(title, kind === 'prescription' ? 'PRESCRIPTION SCANNER' : 'MEDICINE SCANNER', 'Upload a clear image and confirm every extracted detail before using it.', `<div class="upload-box"><div class="upload-icon">⊙</div><h2>Drop a file here</h2><p>JPG, PNG, WEBP or PDF · Max 10 MB</p><input id="scan-file" type="file" accept=".jpg,.jpeg,.png,.webp,.pdf"><label class="primary-button" for="scan-file">Choose file <span>↗</span></label><div id="scan-result"></div></div>`); document.querySelector('#scan-file').addEventListener('change', (event) => { const file = event.target.files[0]; if (!file) return; document.querySelector('#scan-result').innerHTML = `<div class="result-card"><p class="overline teal">CONFIRM BEFORE USING</p><h3>${file.name}</h3><p>File selected successfully. In production, OCR results would appear here with uncertain text visibly marked for your confirmation.</p><p class="safety-note">Never rely on an unreadable medicine name or unclear prescription. Confirm with a doctor or pharmacist.</p></div>`; }); }
async function medicineVideoView(medicine = 'Paracetamol') { featureView('A medicine, <em>in motion.</em>', 'MEDICINE STORIES', 'A short visual explainer made from Medi Dost guidance.', `<div class="medicine-video" data-medicine-video><div class="video-stage"><div class="video-orbit"></div><div class="video-pill">${medicine.slice(0, 2).toUpperCase()}</div><div class="video-pulse"></div><div class="video-copy"><span class="video-step">Loading story...</span><h2>Preparing your explainer</h2><p>Getting the right medicine context from the Medi Dost server.</p></div></div><div class="video-controls"><button class="outline-button" id="video-toggle">Pause <span>Ⅱ</span></button><button class="text-action" id="video-replay">Replay <span>↻</span></button><span class="video-progress"><i></i></span><select id="video-medicine" aria-label="Choose a medicine"><option>Paracetamol</option><option>Cetirizine</option><option>Omeprazole</option><option>ORS</option></select></div><p class="safety-note" data-video-disclaimer></p></div>`); const root = document.querySelector('[data-medicine-video]'); const stage = root.querySelector('.video-stage'); const step = root.querySelector('.video-step'); const title = root.querySelector('.video-copy h2'); const text = root.querySelector('.video-copy p'); const progress = root.querySelector('.video-progress i'); const toggle = document.querySelector('#video-toggle'); const selection = document.querySelector('#video-medicine'); selection.value = medicine; let scenes; let sceneIndex = 0; let playing = true; let timer; const showScene = () => { const scene = scenes[sceneIndex]; step.textContent = `SCENE ${scene.label} · ${medicine.toUpperCase()}`; title.textContent = scene.title; text.textContent = scene.text; stage.dataset.visual = scene.visual; progress.style.width = `${((sceneIndex + 1) / scenes.length) * 100}%`; }; const play = () => { clearInterval(timer); timer = setInterval(() => { sceneIndex = (sceneIndex + 1) % scenes.length; showScene(); }, 4200); }; try { const data = await api('/api/medicine-video', { method: 'POST', body: JSON.stringify({ medicine }) }); scenes = data.scenes; document.querySelector('[data-video-disclaimer]').textContent = data.disclaimer; showScene(); play(); } catch (error) { title.textContent = 'Story unavailable'; text.textContent = error.message; playing = false; } toggle.addEventListener('click', () => { playing = !playing; toggle.innerHTML = playing ? 'Pause <span>Ⅱ</span>' : 'Play <span>▶</span>'; if (playing) play(); else clearInterval(timer); }); document.querySelector('#video-replay').addEventListener('click', () => { sceneIndex = 0; showScene(); playing = true; toggle.innerHTML = 'Pause <span>Ⅱ</span>'; play(); }); selection.addEventListener('change', () => medicineVideoView(selection.value)); }
function toolsView() { shell(`<section class="page"><div class="page-heading"><div><p class="overline teal">HEALTH TOOLS</p><h1>Clarity, <em>at hand.</em></h1><p class="muted">Explore information tools built for everyday health questions.</p></div></div><div class="tools-grid"><button class="tool-card tool-teal" data-view="ai"><span>✦</span><h3>Ask Medi Dost AI</h3><p>Get simple, structured information about medicines and symptoms.</p><b>Open assistant ↗</b></button><button class="tool-card tool-yellow" data-view="interactions"><span>⚗</span><h3>Check interactions</h3><p>Review a medicine combination with a pharmacist-minded safety note.</p><b>Check medicines ↗</b></button><button class="tool-card tool-lavender" data-view="symptoms"><span>⌁</span><h3>Explore symptoms</h3><p>Share duration, severity, and context for possible explanations.</p><b>Open symptom checker ↗</b></button><button class="tool-card tool-peach" data-view="reports"><span>▧</span><h3>Understand a report</h3><p>Upload a lab report and learn what the numbers generally measure.</p><b>Upload report ↗</b></button><button class="tool-card tool-yellow" data-view="prescription"><span>▤</span><h3>Prescription scanner</h3><p>Make a readable list from a prescription with review before use.</p><b>Scan prescription ↗</b></button><button class="tool-card tool-teal" data-view="articles"><span>▦</span><h3>Health library</h3><p>Read practical explainers across medicines, prevention, and wellbeing.</p><b>Browse articles ↗</b></button><button class="tool-card tool-lavender" data-view="compare"><span>⇄</span><h3>Compare medicines</h3><p>Compare general ingredients, uses, and precautions side by side.</p><b>Compare now ↗</b></button><button class="tool-card tool-peach" data-view="scanner"><span>⊙</span><h3>Medicine scanner</h3><p>Upload a strip, box, bottle, or label for confirmation.</p><b>Scan medicine ↗</b></button></div><section class="emergency-panel"><span class="emergency-icon">⚠</span><div><p class="overline">NEED URGENT HELP?</p><h2>Emergencies need people,<br>not an AI.</h2><p>For severe difficulty breathing, chest pain, loss of consciousness, seizure, serious allergic reaction or severe bleeding, contact local emergency services immediately.</p></div><button class="danger-button" id="emergency-button">Emergency help ↗</button></section></section>`); }
function render(view = 'home') { if (view === 'symptoms') symptomsView(); else if (view === 'interactions') interactionsView(); else if (view === 'articles') articlesView(); else if (view === 'compare') compareView(); else if (view === 'scanner') scannerView(); else if (view === 'prescription') scannerView('prescription'); else if (view === 'medicine-video') medicineVideoView(); else if (view === 'ai') aiView(); else if (view === 'medicines') medicinesView(); else if (view === 'saved') savedView(); else if (view === 'reminders') remindersView(); else if (view === 'tools') toolsView(); else if (view === 'reports') reportsView(); else if (view === 'profile') profileView(); else homeView(); window.scrollTo({ top: 0, behavior: 'smooth' }); }
async function boot() { if (localStorage.getItem('medi-dark') === 'true') document.body.classList.add('dark-mode'); app.innerHTML = '<main class="auth-loading"><p>Restoring your Medi Dost session...</p></main>'; try { const response = await fetch(`${API_BASE_URL}/api/auth/me`, { credentials: 'include', headers: { 'Accept': 'application/json' } }); const payload = await response.json(); if (response.status === 401 || payload.authenticated === false) return loginView(); if (!response.ok || !payload.authenticated) throw new Error('Authentication service unavailable.'); render(); } catch (error) { app.innerHTML = `<main class="auth-loading"><p>${error.message || 'Authentication service unavailable.'}</p><button class="outline-button" id="retry-auth">Retry</button></main>`; document.querySelector('#retry-auth').addEventListener('click', boot); } }
async function api(url, options = {}) { const route = url === '/api/login' ? '/api/auth/login' : url; const target = /^https?:\/\//i.test(route) ? route : `${API_BASE_URL}${route}`; const response = await fetch(target, { credentials: 'include', headers: { 'Content-Type': 'application/json' }, ...options }); const contentType = response.headers.get('content-type') || ''; const raw = await response.text(); let payload = null; if (raw.trim()) { try { payload = JSON.parse(raw); } catch { throw new Error(response.ok ? 'The server returned an invalid response. Please try again.' : `The server returned ${response.status} without a valid JSON error.`); } } else if (!response.ok) { throw new Error(`The server returned ${response.status} without a response. Please try again.`); } else if (!contentType.includes('application/json')) { throw new Error('The server returned an unexpected response. Please start the Medi Dost backend.'); } else { throw new Error('The server returned an empty response. Please try again.'); } if (!response.ok) { const message = typeof payload.error === 'string' ? payload.error : payload.error?.message || payload.details?.message || 'Something went wrong.'; throw new Error(message); } if (payload.success && payload.data !== undefined) return payload.data && typeof payload.data === 'object' && !Array.isArray(payload.data) ? { ...payload.data, ...payload } : payload.data; return payload; }

/* Product shell: keeps the existing APIs and authentication while giving each feature its own workspace. */
const uxEscape = (value) => String(value ?? '').replace(/[&<>'"]/g, character => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' }[character]));
const uxIcons = { home: '⌂', ai: '✦', medicines: '▣', reminders: '◷', reports: '▤', tools: '⌘', saved: '♡', profile: '◎' };
const uxNav = (active) => `<aside class="ux-sidebar"><a class="ux-brand" data-ux-view="home" href="#/home"><span class="ux-brand-mark">+</span><span>Medi <b>Dost</b></span></a><p class="ux-nav-label">Workspace</p><nav class="ux-nav" aria-label="Main navigation">${[['home','Home'],['ai','AI Assistant'],['medicines','Medicines'],['reminders','Reminders'],['reports','Health Reports'],['tools','Health Tools']].map(([id,label]) => `<button class="ux-nav-item ${active === id ? 'active' : ''}" data-ux-view="${id}"><span>${uxIcons[id]}</span>${label}</button>`).join('')}</nav><p class="ux-nav-label ux-nav-space">Your space</p><nav class="ux-nav"><button class="ux-nav-item ${active === 'saved' ? 'active' : ''}" data-ux-view="saved"><span>${uxIcons.saved}</span>Saved Medicines</button><button class="ux-nav-item ${active === 'profile' ? 'active' : ''}" data-ux-view="profile"><span>${uxIcons.profile}</span>Profile</button></nav><button class="ux-emergency-link" data-ux-view="emergency"><span>⚕</span><span><b>Emergency Help</b><small>Urgent guidance</small></span><i>↗</i></button><p class="ux-disclaimer">General health information only. Not a replacement for professional medical advice.</p></aside>`;
function uxShell(content, active = 'home', title = 'Medi Dost') { app.innerHTML = `<div class="ux-app-shell">${uxNav(active)}<div class="ux-main"><header class="ux-header"><button class="ux-mobile-menu" aria-label="Open navigation">☰</button><div class="ux-search"><span>⌕</span><input id="global-search" aria-label="Search medicines, symptoms, articles" placeholder="Search medicines, symptoms, articles..." /></div><div class="ux-header-actions"><button class="ux-icon-button" id="theme-toggle" aria-label="Toggle theme">◐</button><button class="ux-language">EN⌄</button><button class="ux-profile-button" data-ux-view="profile"><span>DA</span><b>Devraj Anand</b><small>⌄</small></button></div></header><main class="ux-content" id="page-content" aria-live="polite"><div class="ux-route-title">${title}</div>${content}</main></div></div>`; const theme = document.querySelector('#theme-toggle'); if (theme) theme.addEventListener('click', () => { document.body.classList.toggle('dark-mode'); localStorage.setItem('medi-dark', document.body.classList.contains('dark-mode')); }); }
const uxButton = (label, view, className = 'ux-button') => `<button class="${className}" data-ux-view="${view}">${label}</button>`;
function homeView() { uxShell(`<section class="ux-dashboard-head"><div><p class="ux-eyebrow"><h1>Good morning, Devraj <span>✦</span></h1><p>Here is your calm, clear view of today.</p></div>${uxButton('Health profile ↗', 'profile', 'ux-button secondary')}</section><section class="ux-home-grid"><article class="ux-ai-hero"><div><span class="ux-kicker">✦ MEDI DOST AI</span><h2>Clarity for your<br><em>next health question.</em></h2><p>Ask about medicines, symptoms, or a report in simple language.</p>${uxButton('Open AI Assistant →', 'ai', 'ux-button light')}</div><div class="ux-hero-orb" aria-hidden="true"><span>✦</span><i>+</i></div></article><article class="ux-panel ux-reminder-panel"><div class="ux-panel-heading"><div><p class="ux-eyebrow">TODAY</p><h2>Medicine reminders</h2></div><button class="ux-link" data-ux-view="reminders">View all ↗</button></div><div class="ux-mini-reminder"><span class="ux-time">08:00</span><span class="ux-med-dot mint">✚</span><div><b>Paracetamol</b><small>After breakfast</small></div><span class="ux-status done">Done</span></div><div class="ux-mini-reminder"><span class="ux-time">20:30</span><span class="ux-med-dot blue">✦</span><div><b>Cetirizine</b><small>With water</small></div><button class="ux-status pending">Mark</button></div></article><article class="ux-panel ux-quick-panel"><div class="ux-panel-heading"><div><p class="ux-eyebrow">SHORTCUTS</p><h2>Quick actions</h2></div></div><div class="ux-action-grid">${uxButton('Find a medicine', 'medicines', 'ux-action-card')} ${uxButton('Check symptoms', 'symptoms', 'ux-action-card')} ${uxButton('Add reminder', 'reminders', 'ux-action-card')} ${uxButton('Health tools', 'tools', 'ux-action-card')}</div></article><article class="ux-panel ux-tip-panel"><p class="ux-eyebrow">HEALTH TIP</p><h2>Bring your medicine list to every appointment.</h2><p>A complete list helps your care team check your medicines and supplements together.</p></article><article class="ux-panel ux-recent-panel"><div class="ux-panel-heading"><div><p class="ux-eyebrow">RECENTLY VIEWED</p><h2>Medicine library</h2></div>${uxButton('Browse ↗', 'medicines', 'ux-link')}</div><div class="ux-recent-list"><button data-ux-medicine="1"><span class="ux-med-dot mint">✚</span><b>Paracetamol</b><small>Acetaminophen</small></button><button data-ux-medicine="2"><span class="ux-med-dot blue">✦</span><b>Cetirizine</b><small>Cetirizine HCl</small></button></div></article><article class="ux-emergency-card"><div><span class="ux-alert">⚕</span><div><p class="ux-eyebrow">NEED URGENT HELP?</p><h2>Emergencies need people, not an AI.</h2><p>For severe or life-threatening symptoms, contact local emergency services immediately.</p></div></div>${uxButton('Emergency guidance ↗', 'emergency', 'ux-button danger')}</article></section>`, 'home', 'Home'); }
function aiView(prefill = '') { uxShell(`<section class="ux-page-heading"><div><p class="ux-eyebrow">YOUR HEALTH COMPANION</p><h1>Medi Dost <em>AI</em></h1><p>Thoughtful general information, with safety at the center.</p></div><span class="ux-ready"><i></i> Ready to help</span></section><section class="ux-ai-layout"><aside class="ux-conversation-list"><button class="ux-button primary" id="new-conversation">＋ New conversation</button><p class="ux-eyebrow">RECENT CONVERSATIONS</p><button class="ux-conversation active">Medicine questions <small>Today</small></button><button class="ux-conversation">Understanding symptoms <small>Yesterday</small></button></aside><section class="ux-chat"><header><span class="ux-kicker">✦ MEDI DOST AI</span><span class="ux-source-pill">Local reference</span></header><div class="ux-messages" id="ux-messages"><div class="ux-message assistant"><span>✦</span><div><p>Hello Devraj. What would you like to understand today?</p><small>General information only</small></div></div></div><div class="ux-suggestions"><button data-ux-question="What is paracetamol used for?">What is paracetamol used for?</button><button data-ux-question="What are medicine side effects?">Explain side effects</button><button data-ux-question="Can I check two medicines together?">Check an interaction</button></div><form class="ux-chat-form" id="ux-chat-form"><input id="ux-chat-input" value="${uxEscape(prefill)}" aria-label="Ask Medi Dost AI" placeholder="Ask about a medicine, symptom or report..." required><button type="submit" aria-label="Send message">→</button></form><p class="ux-safety-line">ⓘ Answers are educational, not a diagnosis or prescription.</p></section></section>`, 'ai', 'AI Assistant'); uxBindAI(); }
function uxBindAI() { document.querySelectorAll('[data-ux-question]').forEach(button => button.addEventListener('click', () => { document.querySelector('#ux-chat-input').value = button.dataset.uxQuestion; document.querySelector('#ux-chat-input').focus(); })); document.querySelector('#new-conversation').addEventListener('click', () => { document.querySelector('#ux-messages').innerHTML = '<div class="ux-message assistant"><span>✦</span><div><p>New conversation started. What would you like to understand?</p></div></div>'; }); document.querySelector('#ux-chat-form').addEventListener('submit', async event => { event.preventDefault(); const input = document.querySelector('#ux-chat-input'); const message = input.value.trim(); if (!message) return; const messages = document.querySelector('#ux-messages'); messages.insertAdjacentHTML('beforeend', `<div class="ux-message user"><div><p>${uxEscape(message)}</p></div></div><div class="ux-message assistant typing"><span>✦</span><div><p>Thinking carefully...</p></div></div>`); input.value = ''; try { const result = await api('/api/ai/chat', { method: 'POST', body: JSON.stringify({ message }) }); const answer = result.answer || result.data?.answer || ''; const sections = result.sections || result.data?.sections || []; document.querySelector('.typing').outerHTML = `<div class="ux-message assistant"><span>✦</span><div><p><b>${uxEscape(answer)}</b></p>${sections.map(section => `<p><b>${uxEscape(section.title)}:</b> ${uxEscape(section.text)}</p>`).join('')}<small>${uxEscape(result.safetyNotice || 'General information only')}</small></div></div>`; } catch (error) { document.querySelector('.typing').outerHTML = `<div class="ux-message assistant error"><span>!</span><div><p>${uxEscape(error.message)}</p><button class="ux-link" onclick="render('ai')">Try again</button></div></div>`; } }); }
async function medicinesView() { uxShell(`<section class="ux-page-heading"><div><p class="ux-eyebrow">MEDICINE LIBRARY</p><h1>Find your <em>medicine.</em></h1><p>Search the Medi Dost reference set by name, ingredient, or class.</p></div><span class="ux-source-pill">Verified local reference</span></section><section class="ux-library-tools"><div class="ux-search-field"><span>⌕</span><input id="ux-medicine-search" placeholder="Search medicines or active ingredients..." aria-label="Search medicines"></div><div class="ux-filter-row"><button class="ux-filter active" data-ux-category="">All medicines</button><button class="ux-filter" data-ux-category="Analgesic">Pain relief</button><button class="ux-filter" data-ux-category="Antihistamine">Allergy</button><button class="ux-filter" data-ux-category="Proton">Digestive health</button></div></section><div class="ux-library-grid" id="ux-medicine-grid"><div class="ux-loading">Loading medicine library...</div></div><p class="ux-safety-line">ⓘ Information is educational and source-limited. Confirm important decisions with a doctor or pharmacist.</p>`, 'medicines', 'Medicines'); uxLoadMedicines(); }
async function uxLoadMedicines(query = '') { const grid = document.querySelector('#ux-medicine-grid'); if (!grid) return; grid.innerHTML = '<div class="ux-loading">Searching the medicine reference...</div>'; try { const result = await api(`/api/medicines?q=${encodeURIComponent(query)}`); const items = result.items || result.data?.items || []; grid.innerHTML = items.length ? items.map(uxMedicineCard).join('') : '<div class="ux-empty"><span>⌕</span><h2>No medicines found</h2><p>Try a different name or ingredient.</p></div>'; } catch (error) { grid.innerHTML = `<div class="ux-error"><h2>Medicine library unavailable</h2><p>${uxEscape(error.message)}</p><button class="ux-button secondary" id="ux-retry-medicines">Retry</button></div>`; document.querySelector('#ux-retry-medicines').addEventListener('click', () => uxLoadMedicines(query)); } }
function uxMedicineCard(medicine) { return `<article class="ux-medicine-card"><div class="ux-medicine-symbol">✚</div><button class="ux-save" data-save="${uxEscape(medicine.name)}" aria-label="Save ${uxEscape(medicine.name)}">♡</button><p class="ux-eyebrow">${uxEscape(medicine.className)}</p><h2>${uxEscape(medicine.name)}</h2><p class="ux-generic">${uxEscape(medicine.generic)}</p><p>${uxEscape(medicine.use)}</p><div class="ux-card-footer"><button class="ux-link" data-ux-medicine="${medicine.id}">View details ↗</button><span>${uxEscape(medicine.dosageForm || 'Form unavailable')}</span></div></article>`; }
async function medicineDetailsView(id) { uxShell('<div class="ux-loading">Loading medicine details...</div>', 'medicines', 'Medicine details'); try { const result = await api(`/api/medicines/${id}`); const medicine = result.data || result; uxShell(`<button class="ux-back" data-ux-view="medicines">← Back to medicines</button><section class="ux-detail-head"><div class="ux-medicine-symbol large">✚</div><div><p class="ux-eyebrow">${uxEscape(medicine.className)}</p><h1>${uxEscape(medicine.name)}</h1><p class="ux-detail-generic">${uxEscape(medicine.generic)}</p><button class="ux-button primary" data-save="${uxEscape(medicine.name)}">♡ Save medicine</button></div></section><section class="ux-detail-grid"><article class="ux-panel"><p class="ux-eyebrow">AT A GLANCE</p><dl><dt>Active ingredient</dt><dd>${uxEscape(medicine.generic)}</dd><dt>Dosage form</dt><dd>${uxEscape(medicine.dosageForm || 'Information not available from the selected source.')}</dd><dt>Strength</dt><dd>${uxEscape(medicine.strength || 'Information not available from the selected source.')}</dd><dt>General use</dt><dd>${uxEscape(medicine.use)}</dd></dl></article><article class="ux-panel"><p class="ux-eyebrow">SAFETY INFORMATION</p><h2>Warnings</h2><p>${uxEscape(medicine.warnings)}</p><h2>Common adverse effects</h2><p>${uxEscape(medicine.adverseEffects)}</p><p class="ux-safety-line">Do not change treatment or dose without a qualified healthcare professional.</p></article><article class="ux-panel source"><p class="ux-eyebrow">SOURCE</p><h2>${uxEscape(medicine.source)}</h2><p>Last reviewed: ${uxEscape(medicine.sourceDate || 'Information not available from the selected source.')}</p></article></section>`, 'medicines', 'Medicine details'); } catch (error) { uxShell(`<div class="ux-error"><h2>Medicine details unavailable</h2><p>${uxEscape(error.message)}</p><button class="ux-button secondary" data-ux-view="medicines">Back to library</button></div>`, 'medicines', 'Medicine details'); } }
async function savedView() { uxShell('<div class="ux-loading">Loading your saved medicines...</div>', 'saved', 'Saved Medicines'); try { const result = await api('/api/saved-medicines'); const items = result.data || result; uxShell(`<section class="ux-page-heading"><div><p class="ux-eyebrow">YOUR SPACE</p><h1>Saved <em>medicines.</em></h1><p>Your personal shelf of medicine information.</p></div>${uxButton('Browse library ↗', 'medicines', 'ux-button secondary')}</section><div class="ux-library-grid" id="ux-saved-grid">${items.length ? items.map(uxMedicineCard).join('') : '<div class="ux-empty"><span>♡</span><h2>No saved medicines yet</h2><p>Save a medicine from the library to see it here.</p><button class="ux-button primary" data-ux-view="medicines">Browse medicines</button></div>'}</div>`, 'saved', 'Saved Medicines'); } catch (error) { uxShell(`<div class="ux-error"><h2>Saved medicines unavailable</h2><p>${uxEscape(error.message)}</p><button class="ux-button secondary" data-ux-view="saved">Retry</button></div>`, 'saved', 'Saved Medicines'); } }
async function remindersView() { uxShell(`<section class="ux-page-heading"><div><p class="ux-eyebrow">YOUR ROUTINE</p><h1>Medicine <em>reminders.</em></h1><p>Create prompts for your own routine. They are not prescriptions.</p></div><button class="ux-button primary" id="ux-add-reminder">＋ Add reminder</button></section><section class="ux-reminder-layout"><article class="ux-panel"><div class="ux-panel-heading"><div><p class="ux-eyebrow">UPCOMING</p><h2>Today's reminders</h2></div></div><div id="ux-reminder-list"><div class="ux-loading">Loading reminders...</div></div></article><aside class="ux-panel ux-safety-panel"><span class="ux-alert">◷</span><p class="ux-eyebrow">REMINDER SAFETY</p><h2>Your reminders, your decisions.</h2><p>Only create reminders for schedules confirmed with your doctor or pharmacist.</p></aside></section>`, 'reminders', 'Reminders'); uxLoadReminders(); }
async function uxLoadReminders() { try { const result = await api('/api/reminders'); const items = result.data || result; const list = document.querySelector('#ux-reminder-list'); if (!list) return; list.innerHTML = items.length ? items.map(item => `<div class="ux-reminder-row"><span class="ux-time">${uxEscape(new Date(item.scheduled_at).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }))}</span><span class="ux-med-dot mint">◷</span><div><b>${uxEscape(item.medicine_name)}</b><small>${uxEscape(item.note || 'User-created reminder')}</small></div><span class="ux-status ${item.enabled ? 'pending' : 'done'}">${item.enabled ? 'Active' : 'Off'}</span><button class="ux-icon-button" data-ux-delete-reminder="${item.id}" aria-label="Delete reminder">×</button></div>`).join('') : '<div class="ux-empty small"><span>◷</span><h2>No reminders yet</h2><p>Create a reminder for your own routine.</p></div>'; } catch (error) { document.querySelector('#ux-reminder-list').innerHTML = `<div class="ux-error"><p>${uxEscape(error.message)}</p><button class="ux-button secondary" data-ux-view="reminders">Retry</button></div>`; } }
function uxReminderForm() { const content = `<div class="ux-modal-backdrop" id="ux-reminder-modal"><form class="ux-modal" id="ux-reminder-form"><button type="button" class="ux-modal-close" data-ux-close-modal aria-label="Close">×</button><p class="ux-eyebrow">NEW REMINDER</p><h2>Add a routine prompt</h2><label>Medicine or reminder title<input name="medicineName" required placeholder="e.g. Paracetamol" /></label><label>Date and time<input name="scheduledAt" type="datetime-local" required /></label><label>Notes <textarea name="note" placeholder="Optional note"></textarea></label><div class="ux-modal-actions"><button type="button" class="ux-button secondary" data-ux-close-modal>Cancel</button><button class="ux-button primary">Create reminder</button></div></form></div>`; document.body.insertAdjacentHTML('beforeend', content); document.querySelector('#ux-reminder-form').addEventListener('submit', async event => { event.preventDefault(); const data = Object.fromEntries(new FormData(event.target)); try { await api('/api/reminders', { method: 'POST', body: JSON.stringify(data) }); document.querySelector('#ux-reminder-modal').remove(); uxLoadReminders(); } catch (error) { event.target.insertAdjacentHTML('beforeend', `<p class="ux-error-text">${uxEscape(error.message)}</p>`); } }); }
function reportsView() { uxShell(`<section class="ux-page-heading"><div><p class="ux-eyebrow">PRIVATE HEALTH SPACE</p><h1>Health <em>reports.</em></h1><p>Keep your reports private and available for conversations with your care team.</p></div><button class="ux-button primary" id="ux-report-upload">⊙ Upload report</button></section><section class="ux-empty ux-report-empty"><span>▤</span><h2>No reports yet</h2><p>Secure report storage is not enabled in this local build.</p><small>When enabled, files will require authorization and will not be served publicly.</small></section>`, 'reports', 'Health Reports'); document.querySelector('#ux-report-upload').addEventListener('click', () => toast('Secure report storage is not configured for this local build.')); }
function toolsView() { uxShell(`<section class="ux-page-heading"><div><p class="ux-eyebrow">HEALTH TOOLS</p><h1>Clarity, <em>at hand.</em></h1><p>Focused tools for everyday health information.</p></div></section><div class="ux-tools-grid">${[['bmi','⌁','BMI Calculator','Understand a basic body-mass calculation.'],['symptoms','◌','Symptom Checker','Organize symptoms for a professional conversation.'],['interactions','⚗','Medicine Interactions','Check combinations against the local reference set.'],['comparison','⇄','Medicine Comparison','Compare factual fields without ranking options.'],['water','◒','Water Tracker','Track a personal hydration goal.'],['firstaid','⚕','First Aid Guide','Review general first-aid information.'],['fitness','⌁','Fitness Guide','Explore general movement information.'],['diet','✦','Diet Planner','Plan questions around everyday nutrition.']].map(([id,icon,title,text]) => `<button class="ux-tool-card" data-ux-view="${id}"><span>${icon}</span><h2>${title}</h2><p>${text}</p><b>Open tool ↗</b></button>`).join('')}</div>`, 'tools', 'Health Tools'); }
function uxFeature(id, eyebrow, title, subtitle, body) { uxShell(`<button class="ux-back" data-ux-view="tools">← Back to health tools</button><section class="ux-page-heading"><div><p class="ux-eyebrow">${eyebrow}</p><h1>${title}</h1><p>${subtitle}</p></div></section>${body}`, 'tools', title.replace(/<[^>]+>/g, '')); }
function symptomsView() { uxFeature('symptoms','SYMPTOM CHECKER','Understand your <em>symptoms.</em>','A structured starting point, never a diagnosis.',`<div class="ux-form-panel"><label>What are you experiencing?<textarea id="ux-symptoms" placeholder="For example: fever, cough and sore throat"></textarea></label><label>Severity<select id="ux-severity"><option>Mild</option><option>Moderate</option><option>Severe</option></select></label><button class="ux-button primary" id="ux-symptoms-submit">Explore possibilities →</button><div id="ux-symptoms-result"></div></div>`); document.querySelector('#ux-symptoms-submit').addEventListener('click', async () => { const result = document.querySelector('#ux-symptoms-result'); result.innerHTML = '<div class="ux-loading">Reviewing your information...</div>'; try { const data = await api('/api/symptoms', { method:'POST', body:JSON.stringify({ symptoms:document.querySelector('#ux-symptoms').value, severity:document.querySelector('#ux-severity').value }) }); result.innerHTML = `<div class="ux-result"><h2>General possibilities</h2><p>${uxEscape((data.possible || []).join(' • '))}</p><p><b>Self-care:</b> ${uxEscape(data.selfCare)}</p><p><b>Red flags:</b> ${uxEscape(data.redFlags)}</p></div>`; } catch (error) { result.innerHTML = `<div class="ux-error">${uxEscape(error.message)}</div>`; } }); }
function interactionsView() { uxFeature('interactions','INTERACTION CHECKER','Check medicine <em>interactions.</em>','Only verified local reference results are shown.',`<div class="ux-form-panel"><label>Medicine 1<input id="ux-interaction-a" placeholder="e.g. Paracetamol"></label><label>Medicine 2<input id="ux-interaction-b" placeholder="e.g. Warfarin"></label><button class="ux-button primary" id="ux-interaction-submit">Check combination →</button><div id="ux-interaction-result"></div></div>`); document.querySelector('#ux-interaction-submit').addEventListener('click', async () => { const result = document.querySelector('#ux-interaction-result'); result.innerHTML='<div class="ux-loading">Checking reference data...</div>'; try { const data=await api('/api/interactions/check',{method:'POST',body:JSON.stringify({medicines:[document.querySelector('#ux-interaction-a').value,document.querySelector('#ux-interaction-b').value]})}); result.innerHTML=`<div class="ux-result"><span class="ux-source-pill">${uxEscape(data.result.status)}</span><p>${uxEscape(data.result.detail || data.result.message)}</p></div>`; } catch(error) { result.innerHTML=`<div class="ux-error">${uxEscape(error.message)}</div>`; } }); }
function compareView() { uxFeature('comparison','MEDICINE COMPARISON','Compare with <em>context.</em>','Compare factual fields without recommending an option.',`<div class="ux-form-panel"><div class="ux-compare-selects"><label>Medicine A<select><option>Paracetamol</option><option>Cetirizine</option></select></label><label>Medicine B<select><option>Cetirizine</option><option>Omeprazole</option></select></label></div><div class="ux-result"><h2>Compare factual information</h2><p>Use the medicine library details and confirm personal decisions with a clinician or pharmacist.</p></div></div>`); }
function emergencyView() { uxShell(`<section class="ux-emergency-page"><span class="ux-alert large">⚕</span><p class="ux-eyebrow">URGENT SUPPORT</p><h1>Emergencies need <em>people.</em></h1><p class="ux-emergency-lead">For severe difficulty breathing, chest pain, loss of consciousness, seizure, severe bleeding, overdose, or a serious allergic reaction, contact local emergency services immediately.</p><div class="ux-emergency-actions"><button class="ux-button danger" id="ux-emergency-call">Call local emergency services</button><button class="ux-button secondary" data-ux-view="home">Return to dashboard</button></div><p class="ux-safety-line">Medi Dost cannot assess or treat emergencies.</p></section>`, 'emergency', 'Emergency Help'); document.querySelector('#ux-emergency-call').addEventListener('click', () => toast('Please contact your local emergency service now.')); }
function profileView() { uxShell(`<section class="ux-page-heading"><div><p class="ux-eyebrow">YOUR SPACE</p><h1>Profile <em>& settings.</em></h1><p>Keep your account preferences clear and in your hands.</p></div></section><div class="ux-profile-grid"><article class="ux-panel"><p class="ux-eyebrow">PERSONAL INFORMATION</p><div class="ux-profile-identity"><span>DA</span><div><h2>Devraj Anand</h2><p>devraj@example.com</p></div></div><button class="ux-button secondary">Edit profile</button></article><article class="ux-panel"><p class="ux-eyebrow">PREFERENCES</p><label class="ux-toggle-row">Language <select><option>English</option><option>Hindi</option><option>Hinglish</option></select></label><label class="ux-toggle-row">Notifications <input type="checkbox" checked></label></article><article class="ux-panel"><p class="ux-eyebrow">PRIVACY & SECURITY</p><h2>Your information is yours.</h2><p>Sessions are protected by an HttpOnly cookie. Health information is not shared by this interface.</p><button class="ux-link">Privacy settings ↗</button></article><article class="ux-panel"><p class="ux-eyebrow">ACCOUNT</p><button class="ux-button danger" id="ux-logout">Log out</button></article></div>`, 'profile', 'Profile'); }
function uxRouteFromHash() { const route = location.hash.replace(/^#\//, '') || 'home'; return route.split('/'); }
function render(view = 'home') { const route = Array.isArray(view) ? view : String(view).split('/'); const name = route[0] || 'home'; if (name === 'ai') aiView(); else if (name === 'medicines' && route[1]) medicineDetailsView(route[1]); else if (name === 'medicines') medicinesView(); else if (name === 'saved') savedView(); else if (name === 'reminders') remindersView(); else if (name === 'reports') reportsView(); else if (name === 'tools') toolsView(); else if (name === 'bmi') uxFeature('bmi','HEALTH CALCULATOR','BMI <em>calculator.</em>','A deterministic educational calculation, not a diagnosis.','<div class="ux-form-panel"><label>Weight (kg)<input type="number" id="ux-weight" min="1"></label><label>Height (cm)<input type="number" id="ux-height" min="1"></label><button class="ux-button primary" id="ux-bmi-submit">Calculate BMI</button><div id="ux-bmi-result"></div></div>'); else if (name === 'symptoms') symptomsView(); else if (name === 'interactions') interactionsView(); else if (name === 'comparison') compareView(); else if (['water','firstaid','fitness','diet'].includes(name)) uxFeature(name,'HEALTH TOOL',`${name[0].toUpperCase()}${name.slice(1)} <em>guide.</em>`,'A calm starting point for general health information.',`<div class="ux-form-panel"><div class="ux-result"><h2>Educational tool</h2><p>This focused guide is ready to connect to verified content. It does not diagnose, prescribe, or replace professional advice.</p></div></div>`); else if (name === 'profile') profileView(); else if (name === 'emergency') emergencyView(); else homeView(); window.scrollTo({ top: 0, behavior: 'smooth' }); }
async function boot() { if (localStorage.getItem('medi-dark') === 'true') document.body.classList.add('dark-mode'); document.querySelector('#app').innerHTML = '<main class="auth-loading"><p>Restoring your Medi Dost session...</p></main>'; try { const response = await fetch(`${API_BASE_URL}/api/auth/me`, { credentials: 'include', headers: { Accept: 'application/json' } }); const payload = await response.json(); if (response.status === 401 || payload.authenticated === false) return loginView(); if (!response.ok || !payload.authenticated) throw new Error('Authentication service unavailable.'); render(uxRouteFromHash()); } catch (error) { document.querySelector('#app').innerHTML = `<main class="auth-loading"><p>${uxEscape(error.message || 'Authentication service unavailable.')}</p><button class="outline-button" id="retry-auth">Retry</button></main>`; document.querySelector('#retry-auth').addEventListener('click', boot); } }
document.addEventListener('click', event => { const view = event.target.closest('[data-ux-view]'); if (view) { event.preventDefault(); const next = view.dataset.uxView; location.hash = `#/${next}`; render(next); } const medicine = event.target.closest('[data-ux-medicine]'); if (medicine) { event.preventDefault(); location.hash = `#/medicines/${medicine.dataset.uxMedicine}`; render(`medicines/${medicine.dataset.uxMedicine}`); } const category = event.target.closest('[data-ux-category]'); if (category) { document.querySelectorAll('.ux-filter').forEach(item => item.classList.remove('active')); category.classList.add('active'); uxLoadMedicines(category.dataset.uxCategory || ''); } const close = event.target.closest('[data-ux-close-modal]'); if (close) document.querySelector('#ux-reminder-modal')?.remove(); const deleteReminder = event.target.closest('[data-ux-delete-reminder]'); if (deleteReminder) api(`/api/reminders/${deleteReminder.dataset.uxDeleteReminder}`, { method: 'DELETE' }).then(uxLoadReminders); const save = event.target.closest('[data-save]'); if (save && save.dataset.uxHandled !== 'true') { save.dataset.uxHandled = 'true'; api('/api/saved-medicines', { method: 'POST', body: JSON.stringify({ name: save.dataset.save }) }).then(() => { save.textContent = '♥ Saved'; toast('Medicine saved'); }).catch(error => toast(error.message)); } if (event.target.closest('#ux-add-reminder')) uxReminderForm(); if (event.target.closest('#ux-logout')) api('/api/logout', { method: 'POST' }).then(() => loginView()); });
document.addEventListener('input', event => { if (event.target.id === 'ux-medicine-search') { clearTimeout(window.uxSearchTimer); window.uxSearchTimer = setTimeout(() => uxLoadMedicines(event.target.value.trim()), 250); } });
window.addEventListener('hashchange', () => render(uxRouteFromHash()));
boot();

function loginView(error = '') {
  app.innerHTML = `<main class="login-page"><div class="login-art"><a class="logo" href="#"><span class="logo-mark">+</span><span>Medi <b>Dost</b></span></a><div class="login-orbit"><span>✦</span><b>+</b></div><div><p class="overline">YOUR SMART FRIEND FOR BETTER HEALTH</p><h1>Health questions?<br><em>Ask Medi Dost.</em></h1><p>Clear, careful health information for the moments you need it.</p></div></div><section class="login-card"><div class="login-card-heading"><span class="ai-badge"><span>✦</span> Welcome back</span><h2>Sign in to<br><em>Medi Dost.</em></h2><p>Continue your health journey with your personal companion.</p></div><form id="login-form"><label for="login-email">Email address</label><input id="login-email" type="email" value="devraj@example.com" placeholder="you@example.com" required><label for="login-password">Password</label><div class="password-field"><input id="login-password" type="password" value="medidost123" placeholder="Your password" required><button type="button" id="show-password">Show</button></div><p class="login-error" id="login-error">${uxEscape(error)}</p><button class="primary-button login-button" type="submit">Sign in <span>→</span></button><p class="login-legal">By continuing, you agree that Medi Dost provides general health information and does not replace a qualified doctor, pharmacist, or emergency service.</p></form></section></main>`;
  document.querySelector('#login-form').addEventListener('submit', async event => { event.preventDefault(); const errorEl = document.querySelector('#login-error'); const button = event.target.querySelector('button[type="submit"]'); button.disabled = true; button.textContent = 'Signing in...'; try { await api('/api/auth/login', { method: 'POST', body: JSON.stringify({ email: document.querySelector('#login-email').value, password: document.querySelector('#login-password').value }) }); location.hash = '#/home'; render('home'); } catch (loginError) { errorEl.textContent = loginError.message; button.disabled = false; button.innerHTML = 'Sign in <span>→</span>'; } });
  document.querySelector('#show-password').addEventListener('click', () => { const input = document.querySelector('#login-password'); input.type = input.type === 'password' ? 'text' : 'password'; });
}
